import * as userDefinedStores from './stores.js'

const validStore = (store) => typeof store === 'function' && store.name === 'useStore' && store.$id

const useStores = () => {
  const stores = {}

  Object.values(userDefinedStores)
    .filter(validStore)
    .forEach((store) => {
      stores[store.$id] = store()
    })

  return stores
}

export { validStore, useStores }
